+            // Puts each item in the free cell closest to where it was dropped,
+            // and remembers how far from that cell it has to be drawn.
+            function moveFreely(dropPos, urls) {
+                const rows = (gridView.flow === GridView.FlowLeftToRight);
+                const rtl = (gridView.effectiveLayoutDirection === Qt.RightToLeft);
+                const stripes = Math.max(positioner.optimalStripes, Math.ceil(gridView.count / positioner.perStripe));
+                const cellsX = rows ? positioner.perStripe : stripes;
+                const cellsY = rows ? stripes : positioner.perStripe;
+
+                let items = [];
+                for (let i = 0; i < urls.length; i++) {
+                    const from = positioner.indexForUrl(urls[i]);
+                    if (from === -1) {
+                        continue;
+                    }
+                    const offset = dir.dragCursorOffset(positioner.map(from));
+                    if (offset.x === -1) {
+                        continue;
+                    }
+                    items.push({url: urls[i], from: from, x: dropPos.x + offset.x, y: dropPos.y + offset.y});
+                }
+
+                const fromIndices = items.map(item => item.from);
+                let taken = [];
+                let moves = [];
+
+                // Candidate cells along one axis, nearest first, with the item's offset from each
+                const candidates = (pos, cells) => {
+                    const first = Math.max(0, Math.floor(pos));
+                    let result = [first, first + 1]
+                        .filter(cell => cells <= 0 || cell < cells)
+                        .map(cell => {
+                            let offset = pos - cell;
+                            if ((cell === 0 && offset < 0) || (cells > 0 && cell === cells - 1 && offset > 0)) {
+                                offset = 0;
+                            }
+                            return {cell: cell, offset: offset};
+                        });
+                    if (!result.length) {
+                        result = [{cell: cells - 1, offset: 0}];
+                    }
+                    return result.sort((a, b) => Math.abs(a.offset) - Math.abs(b.offset));
+                };
+
+                for (const item of items) {
+                    let x = item.x;
+                    if (rtl) {
+                        x -= (rows ? gridView.contentX : gridView.originX);
+                        x = (rows ? gridView.width : gridView.contentItem.width) - x - gridView.cellWidth;
+                    }
+
+                    let options = [];
+                    for (const cx of candidates(x / gridView.cellWidth, cellsX)) {
+                        for (const cy of candidates(item.y / gridView.cellHeight, cellsY)) {
+                            const to = rows ? (cy.cell * positioner.perStripe + cx.cell) : (cx.cell * positioner.perStripe + cy.cell);
+                            const offset = Qt.point(rtl ? -cx.offset : cx.offset, cy.offset);
+                            options.push({to: to, offset: offset});
+                        }
+                    }
+                    options.sort((a, b) => Math.hypot(a.offset.x, a.offset.y) - Math.hypot(b.offset.x, b.offset.y));
+
+                    const free = to => !taken.includes(to)
+                        && (to >= gridView.count || positioner.isBlank(to) || fromIndices.includes(to));
+                    const choice = options.find(option => free(option.to)) ?? {to: options[0].to, offset: Qt.point(0, 0)};
+
+                    taken.push(choice.to);
+                    positioner.setOffset(item.url, choice.offset);
+                    if (item.from !== choice.to) {
+                        moves.push(item.from);
+                        moves.push(choice.to);
+                    }
+                }
+
+                if (moves.length) {
+                    gridView.currentIndex = positioner.move(moves);
+                    gridView.forceLayout();
+                }
+
+                main.generateDragImage(); // in case the user drags again
+            }
