+void Positioner::setOffset(const QUrl &url, const QPointF &offset)
+{
+    const int row = indexForUrl(url);
+    if (row == -1 || !m_proxyToSource.contains(row)) {
+        return;
+    }
+
+    const QString key = m_folderModel->data(m_folderModel->index(m_proxyToSource.value(row), 0), FolderModel::UrlRole).toString();
+
+    if (offset.isNull()) {
+        if (!m_offsets.remove(key)) {
+            return;
+        }
+    } else if (m_offsets.value(key) == offset) {
+        return;
+    } else {
+        m_offsets.insert(key, offset);
+    }
+
+    const QModelIndex &idx = index(row, 0);
+    Q_EMIT dataChanged(idx, idx, {OffsetRole});
+
+    saveOffsets();
+}
+
+void Positioner::loadOffsets()
+{
+    m_offsets.clear();
+
+    const QJsonObject offsets = QJsonDocument::fromJson(m_applet->config().group(u"General"_s).readEntry(u"positionOffsets"_s).toUtf8()).object();
+
+    for (auto it = offsets.begin(); it != offsets.end(); ++it) {
+        const QJsonArray offset = it.value().toArray();
+        if (offset.size() == 2) {
+            m_offsets.insert(it.key(), QPointF(offset[0].toDouble(), offset[1].toDouble()));
+        }
+    }
+}
+
+void Positioner::saveOffsets()
+{
+    if (!m_applet) {
+        return;
+    }
+
+    QJsonObject offsets;
+
+    for (auto it = m_offsets.cbegin(); it != m_offsets.cend(); ++it) {
+        offsets.insert(it.key(), QJsonArray{it.value().x(), it.value().y()});
+    }
+
+    auto config = m_applet->config().group(u"General"_s);
+    if (offsets.isEmpty()) {
+        config.deleteEntry(u"positionOffsets"_s);
+    } else {
+        config.writeEntry(u"positionOffsets"_s, QJsonDocument(offsets).toJson(QJsonDocument::Compact));
+    }
+    Q_EMIT m_applet->configNeedsSaving();
+}
